// RemovePro relationship.
// Sets o.R.Pro to nil.
// Removes o from all passed in related items' relationships struct.
func (o *AgendaItem) RemovePro(ctx context.Context, exec boil.ContextExecutor, related *Produto) error {
	var err error

	queries.SetScanner(&o.ProID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("pro_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Pro = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.ProAgendaItems {
		if queries.Equal(o.ProID, ri.ProID) {
			continue
		}

		ln := len(related.R.ProAgendaItems)
		if ln > 1 && i < ln-1 {
			related.R.ProAgendaItems[i] = related.R.ProAgendaItems[ln-1]
		}
		related.R.ProAgendaItems = related.R.ProAgendaItems[:ln-1]
		break
	}
	return nil
}

